        /// Target-triple to compile the application for
        required triple: OsString
        /// Compile without web server support
        optional --no-web
    }

    /// Native release build (plugins + binary, no cross-compilation)
    cmd build-release {
        /// Compile without web server support
        optional --no-web
    }
}

/// Run the in-process whole-app integration tests
cmd integration-test {
    /// Build with the default dev profile instead of dev-opt
    /// (skips the one-time optimized dependency build, tests run ~7x slower)
    optional --no-opt
    /// Run the tests one at a time instead of in parallel
    optional --serial
    /// Arguments to pass to the test runner
    repeated args: OsString
}

fn main() -> anyhow::Result<()> {
    let shell = &Shell::new()?;

    let flags = flags::Xtask::from_env()?;
    let now = Instant::now();

    match flags.subcommand {
        flags::XtaskCmd::Deprecated(_flags) => deprecation_notice(),
        flags::XtaskCmd::Build(flags) => build::build(shell, flags),
        flags::XtaskCmd::Format(flags) => format::format(shell, flags),
        flags::XtaskCmd::Test(flags) => test::test(shell, flags),
        flags::XtaskCmd::IntegrationTest(flags) => integration_test::integration_test(shell, flags),
        flags::XtaskCmd::Proto(_flags) => build::proto(shell),
        flags::XtaskCmd::Assets(flags) => assets::assets(shell, flags),

